def assign_anon_numbers(apps, schema_editor):
    """기존 멤버십에 익명 번호 부여: 방장 0, 나머지는 들어온 순서대로 1, 2, ..."""
    ChatRoomMemberShip = apps.get_model("chatting", "ChatRoomMemberShip")

    numbers = {}  # (chat_room_id, user_id) -> anon_number
    next_number = {}  # chat_room_id -> 다음 번호
    for membership in ChatRoomMemberShip.objects.order_by("id"):
        key = (membership.chat_room_id, membership.user_id)
        if key not in numbers:
            if membership.role == "OWNER":
                numbers[key] = 0
            else:
                numbers[key] = next_number.get(membership.chat_room_id, 1)
                next_number[membership.chat_room_id] = numbers[key] + 1
        membership.anon_number = numbers[key]
        membership.save(update_fields=["anon_number"])


def remove_observer_role(apps, schema_editor):
    """관전자(OBSERVER) 역할 제거: 있으면 참여자로"""
    ChatRoomMemberShip = apps.get_model("chatting", "ChatRoomMemberShip")
    ChatRoomInvitation = apps.get_model("chatting", "ChatRoomInvitation")
    ChatRoomMemberShip.objects.filter(role="OBSERVER").update(role="PARTICIPANT")
    ChatRoomInvitation.objects.filter(invitation_role="OBSERVER").update(invitation_role="PARTICIPANT")


